"""Public method exported from authenticated target source2e96cfc5,2026-10-19."""
class HumanSession:
    def _check_identity_and_budget(self, row):
        require('governedWindowRenewal' in row, 'EXPLICIT_TEST_SUCCESSOR_BUDGET_RECEIPT_REQUIRED')
        binding = row.get('binding', {})
        require(row.get('schema') == 'ouf.chatbot-human-session.private.v1' and binding.get('selectionHash') == digest(self.selection) and (binding.get('issuer') == self.selection['issuer']) and (binding.get('subject') == self.selection['subject']) and (binding.get('tenant') == self.selection['tenant']) and (binding.get('clientId') == CLIENT) and (binding.get('scopes') in (LEGACY_SCOPES, SCOPES)) and (binding.get('tokenPath') == str(self.token_path)) and (binding.get('sessionDirectory') == str(self.directory)) and (binding.get('expiresAt') == self.expires_at) and (binding.get('retryProfile') == PROFILE) and (row.get('budgetReset') is False) and (row.get('bootId') == self._boot()), 'HUMAN_SESSION_BINDING_OR_HISTORY_DRIFT')
        require(type(row.get('attempts')) is int and 0 <= row['attempts'] <= PROFILE['maximumAttempts'], 'HUMAN_SESSION_BUDGET_DRIFT')
        if 'governedWindowRenewal' in row:
            receipt = row['governedWindowRenewal']
            review = receipt['review']
            decision = receipt['decision']
            require((review.get('schema') == 'ouf.human-explicit-test-budget-review.v2' and review.get('predecessorMaximumCumulativeOAuthAttempts') == 128 and (type(review.get('priorOAuthAttempts')) is int) and (124 <= review['priorOAuthAttempts'] <= 128) or (review.get('schema') == 'ouf.human-explicit-test-continuation-review.v3' and review.get('predecessorMaximumCumulativeOAuthAttempts') == 256 and (type(review.get('priorOAuthAttempts')) is int) and (129 <= review['priorOAuthAttempts'] < 256) and (review.get('freshIssuerAuthenticationRequired') is True) and (review.get('failedRefreshReplayAllowed') is False) and (review.get('budgetReset') is False)) or (review.get('schema') == 'ouf.human-explicit-capability-scope-review.v4' and review.get('predecessorMaximumCumulativeOAuthAttempts') == 256 and (type(review.get('priorOAuthAttempts')) is int) and (129 <= review['priorOAuthAttempts'] < 256) and (review.get('requestedScopes') == SCOPES) and (review.get('previousScopes') == LEGACY_SCOPES) and (binding.get('scopes') == SCOPES) and (review.get('freshIssuerAuthenticationRequired') is True) and (review.get('budgetReset') is False))) and review.get('purpose') == 'CONFIGURATION_AND_VALIDATION' and (review['maximumCumulativeOAuthAttempts'] == PROFILE['maximumAttempts']) and (row['attempts'] >= review['priorOAuthAttempts']) and (decision['reviewHash'] == digest(review)) and (binding['createdAt'] == decision['approvedAt']) and (binding['expiresAt'] == decision['expiresAt']) and (decision['expiresAt'] - decision['approvedAt'] == PROFILE['maximumElapsedSeconds']), 'RENEWED_HUMAN_WINDOW_CUMULATIVE_HISTORY_REQUIRED')
